const { spawn, spawnSync } = require('node:child_process');
const { join } = require('node:path');
const options = { stdio: 'inherit' };
let child;

if (process.platform === 'win32') {
  const where = join(process.env.SystemRoot, 'System32', 'where.exe');
  const installed = spawnSync(where, ['/q', '$PATH:tlaplus-mcp']).status === 0;
  child = spawn(process.env.ComSpec ?? 'cmd.exe', ['/d', '/s', '/c', installed ? 'tlaplus-mcp' : 'npx -y @tlaplus-mcp/tlaplus-mcp'], {
    ...options,
    env: installed ? { ...process.env, NoDefaultCurrentDirectoryInExePath: '1' } : process.env
  });
} else {
  child = spawn('/bin/sh', ['-c', 'if [ -n "$(command -v tlaplus-mcp)" ]; then\n  exec tlaplus-mcp\nfi\nexec npx -y @tlaplus-mcp/tlaplus-mcp'], options);
}

const signals = ['SIGHUP', 'SIGINT', 'SIGTERM'];
const forward = (signal) => child.kill(signal);
for (const signal of signals) {
  process.on(signal, forward);
}
child.once('error', (error) => console.error(error.message));
child.once('close', (code, signal) => {
  for (const name of signals) {
    process.removeListener(name, forward);
  }
  if (signal !== null && process.platform !== 'win32') {
    process.kill(process.pid, signal);
  } else {
    process.exitCode = code ?? 1;
  }
});
